// THE TURN'S OUTBOUND MESSAGES, IN ORDER — and there may be more than one now.
//
// This was `runOnceForEachItem` and emitted exactly one text body. A product list is
// SEVERAL messages (a sentence, then cards, then "See more"), and they are composed by
// jovi-mall rather than here: `channel-reply.ts` is the one place that knows a WhatsApp
// reply-button title is capped at twenty characters and that a carousel is a template with
// a fixed card count. What arrives here is a ready array of request bodies.
//
// ⚠ ORDER IS THE RENDERING. The sentence goes first, then the cards. `send guard`,
// `is telegram?` and both send nodes iterate their input items in order, so emitting the
// array is all it takes — do not sort it, do not fan it out.
//
// ⚠ Reads `$('AI Agent')` explicitly rather than `$input`. Its immediate predecessor is now
// a Redis DELETE, whose output is an API result and not the model's answer.
const inbound = $('Inbound').first().json;
const sync = $('sync identity').first().json;

// ── The cards the display tool drew, if it ran ──────────────────────────────
//
// wi-mall-product-cards writes the channel-ready bodies to Redis rather than returning
// them, because a tool result lands in the MODEL's context where a sendPhoto body can do
// nothing. Same gate-echo mechanism the bargaining tools use, for the same reason.
//
// ⚠ The value carries its own `expiresAt` AND its own `__messageId`, and both are checked.
// The n8n Redis node's `set` exposes no TTL — measured, and the reason the product-search
// query cache lives in Postgres — so a key can outlive its turn. Sending last turn's cards
// under this turn's sentence is worse than sending none.
let cards = [];
try {
  const echoRaw = $('check display').first().json.displayEcho;
  const echo = echoRaw ? JSON.parse(String(echoRaw)) : null;
  const fresh = !!echo && !!echo.expiresAt && new Date(echo.expiresAt).getTime() > Date.now();
  const mine = !!echo && String(echo.__messageId || '') === String(inbound.messageId || '');
  if (echo && fresh && mine && Array.isArray(echo.replies)) {
    cards = echo.replies.filter(function (r) { return r && r.channel && r.method && r.body; });
  }
} catch (e) {
  cards = [];
}

const answer = String($('AI Agent').first().json.output ?? '').trim();

// ⚠ The stand-in is SUPPRESSED when there are cards. An empty model turn is a failure only
// when nothing else is going out; over a page of products it would put "Sorry, I could not
// answer that just now" above five things we had just found for them.
const standIn = cards.length > 0
  ? ''
  : String(sync && sync.data && sync.data.fallback ? sync.data.fallback.assistantUnavailable : '').trim();

const chosen = answer || standIn;
const text = chosen.length > 4000 ? chosen.slice(0, 3997) + '…' : chosen;

const out = [];

if (text) {
  out.push({ json: { reply: inbound.channel === 'telegram'
    ? { channel: 'telegram', method: 'sendMessage', body: { chat_id: String(inbound.externalId), text: text } }
    : { channel: 'whatsapp', method: 'messages', body: {
        messaging_product: 'whatsapp', recipient_type: 'individual',
        to: String(inbound.externalId), type: 'text', text: { body: text } } } } });
}

cards.forEach(function (reply) { out.push({ json: { reply: reply } }); });

// `send guard` drops a null reply. Emitting one item rather than none keeps this branch the
// exact shape it has always been for a turn with nothing to say.
if (out.length === 0) { out.push({ json: { reply: null } }); }

return out;

// What the model is actually asked, for an ordinary agent turn.
//
// ⚠ THIS USED TO SAY THE MODEL COULD NOT SEE THE FILE, AND THAT IS NO LONGER TRUE.
// wi-mall-perceive renders a picture, a voice note or a video into text before we get
// here. Three different things come back and they are NOT interchangeable:
//
//   audio  -> a TRANSCRIPT. That IS the customer's message, so it becomes the turn
//             itself rather than a note about a turn.
//   image  -> a DESCRIPTION written by another model. The agent still cannot see, so it
//    video    must speak only about what the description mentions and never claim to
//             have looked at it.
//
// Perceiving and STORING are separate questions and separate branches. A voice note is
// understood and never uploaded, because the backend allowlist is images and PDF only.
const inbound = $('Inbound').item.json;
const typed = String(inbound.text || '').trim();

let note = '';
let spoken = '';

// Referencing a node that did not run in this execution THROWS, so ask first.
if (inbound.kind === 'media' && $('call perceive').isExecuted) {
  const p = $('call perceive').item.json || {};
  const body = (p && p.perceived === true) ? String(p.text || '').trim() : '';

  if (body && p.kind === 'audio') {
    spoken = body;
    note = '[The customer sent this as a VOICE NOTE. Answer it exactly as if they had typed it, in the language they spoke. Never mention transcription.]';
  } else if (body && p.kind === 'video') {
    note = '[The customer sent a VIDEO. You cannot watch it. A model that did describes it as: ' + body + ' Speak only about what that description mentions, and never claim to have watched it.]';
  } else if (body) {
    note = '[The customer sent a PICTURE. You cannot see it. A model that did describes it as: ' + body + ' Speak only about what that description mentions, and never claim to have seen it.]';
  } else {
    note = '[The customer sent a file and it could not be read. Say so plainly and ask them to describe it, or to send it again.]';
  }
}

// The storage handle, when the file was one the backend accepts. Only reachable through
// `is storable?`, so audio and video never land here.
if (inbound.kind === 'media' && $('upload inbound file').isExecuted) {
  const res = $('upload inbound file').item.json || {};
  const d = res.data;
  if (res.success && d && d.ref) {
    note = note + ' [It is also stored as ' + d.fileName + ' (' + d.kind + '), reference ' + d.ref + '. Pass that exact string as ref to tickets_add_attachment if it belongs on a support ticket; open the ticket first if there is not one. The reference works ONCE and expires in 30 minutes.]';
  } else {
    // The SENTENCE is the backend's, already in the customer's language: n8n holds no
    // copy table and no translator. See api-doc/n8n/bot-surface.md 11.4.
    const msg = res.error ? String(res.error.customerMessage || '').trim() : '';
    if (msg) {
      note = note + ' [It could not be stored. If they ask to attach it to anything, tell them exactly this, in their language: ' + msg + ']';
    }
  }
}

const agentInput = [note, typed || spoken].filter(Boolean).join(' ').trim();

return { json: { agentInput: agentInput || null } };

// EVERY MESSAGE THIS TURN COMPOSED GOES OUT — AND THE MAIN AGENT'S SENTENCE IS SUPPRESSED WHEN
// THE BARGAINER HAS ALREADY SPOKEN.
//
// ── Why this node now returns ALL items (fixed 2026-09-16) ─────────────────────
// `compose agent reply` emits the turn as SEVERAL items since product cards landed: the
// agent's sentence first (when there is one), then each card body the display tool echoed.
// This node used to read `$(nm).first()` and return ONE item, so every card after the first
// item was silently dropped — a customer who asked for products got the sentence and no
// products. `send guard`, `is telegram?` and both send nodes iterate their input items in
// order, so returning the items in order is the whole fix. ⚠ Never sort them: order IS the
// rendering (sentence, then cards, then "See more").
//
// ── The bargaining suppression (unchanged in purpose) ────────────────────────
// `open_negotiation` chains into a full bargaining turn, so the customer is sent the gate's
// approved sentence from INSIDE the agent's tool call. The agent still composes a final answer
// afterwards, and without this the customer gets two messages: the negotiated price, then a
// line saying the price is being looked at. The sentence stays the BARGAINER'S (D-4).
//
// ⚠ What is suppressed is the AGENT'S SENTENCE — never the cards. A turn that both bargained
// and showed products keeps its products.
//
// How the sentence is recognised, without guessing and without re-reading the display echo:
// `compose agent reply` emits a sentence exactly when (a) the model wrote something — then it
// is ALWAYS the first item — or (b) the model wrote nothing AND there were no cards, in which
// case it emits the backend's stand-in sentence as the ONLY item. So: drop item 0 when the
// model spoke; otherwise drop a single item only when it IS the stand-in, word for word. A
// card can never equal the stand-in, and the fallback nodes emit nothing but a sentence.
//
// The echo is written ONLY after wi-mall-bargain's send returned, is stamped with this turn's
// messageId, carries its own expiry (the n8n Redis node's `set` exposes no TTL) and is deleted
// on read. A stale, mismatched or malformed echo is not an answer.
//
// Fails toward an extra message, never toward silence: with Redis unreachable the customer
// keeps the counter-offer and also gets the bridging line.
const inbound = $('Inbound').first().json;

let source = null;
for (const nm of ['compose agent reply', 'agent fallback', 'outage fallback']) {
  if ($(nm).isExecuted) { source = nm; break; }
}
if (source == null) { return [{ json: { reply: null } }]; }

const replies = $(source).all()
  .map(function (item) { return (item.json || {}).reply || null; })
  .filter(function (reply) { return reply != null; });

let answered = false;
if ($('read bargain echo').isExecuted) {
  const raw = ($('read bargain echo').first().json || {}).bargainAnswered;
  try {
    const echo = raw ? JSON.parse(String(raw)) : null;
    const live = !!echo && !!echo.expiresAt && new Date(echo.expiresAt).getTime() > Date.now();
    if (live && String(echo.messageId) === String(inbound.messageId)) { answered = true; }
  } catch (e) { /* a malformed echo is not an answer */ }
}

let out = replies;

if (answered) {
  if (source !== 'compose agent reply') {
    // The fallbacks emit a sentence and nothing else.
    out = [];
  } else {
    const modelSpoke = String(($('AI Agent').first().json || {}).output ?? '').trim() !== '';
    const sync = $('sync identity').first().json;
    const standIn = String(sync && sync.data && sync.data.fallback ? sync.data.fallback.assistantUnavailable : '').trim();
    const textOf = function (reply) {
      const body = (reply && reply.body) || {};
      if (typeof body.text === 'string') return body.text;
      if (body.text && typeof body.text.body === 'string') return body.text.body;
      return null;
    };

    if (modelSpoke) {
      out = replies.slice(1);
    } else if (replies.length === 1 && standIn !== '' && textOf(replies[0]) === standIn) {
      out = [];
    }
  }
}

if (out.length === 0) { return [{ json: { reply: null } }]; }
return out.map(function (reply) { return { json: { reply: reply } }; });

// IS THIS MESSAGE A COMMAND? — and deliberately nothing more than that.
//
// ⭐ THE VOCABULARY MOVED SERVER-SIDE ON 2026-09-09, and this node used to hold it: every
// command name, every alias, and the argument grammar. It holds none of them now. The
// reason is the one `bot-surface.md` § 14.6 already gives about parsing a typed answer:
//
//   "A typed answer is language-dependent and whatever reads it is not... That table would
//    have lived in the automation layer, which is the one layer with no copy table."
//
// The alias table IS a five-language table — /chercher /buscar /procurar, /annuler
// /cancelar. Keeping it here meant a vocabulary nobody translates, nobody reviews and
// nobody notices has gone stale. jovi-mall parses now, and answers with a channel-ready
// reply like every other turn.
//
// ⚠ THE RAW TEXT IS WHAT TRAVELS. Never Telegram's bot_command entity: it stops at a
// hyphen, which is why /reset-password could only ever be read as /reset plus trailing
// text — and why the vocabulary is now one word with no separators at all.

const inbound = $('Inbound').first().json;
const sync = $input.first().json;

let kind = '';
let payload = {};

const text = typeof inbound.text === 'string' ? inbound.text.trim() : '';
const onboardingPending = !!(sync && sync.data && sync.data.onboarding && sync.data.onboarding.next);

// A failed /identity/sync is `route turn`'s business — a 4xx body renders its own refusal.
if (sync && sync.success !== false) {
  if (inbound.kind === 'contact' && inbound.contact && !onboardingPending) {
    // ⚠ A CONTACT IS A TAP, NOT TYPED TEXT, so it keeps the webhook command bus rather than
    // going to the parser. It also runs ONLY once onboarding is finished: while the
    // checklist still wants the phone step, `route onboarding` must have the contact — it
    // is the same number, and binding it there is what completes registration. Afterwards a
    // contact can only be answering the request_contact keyboard /login or /password put
    // up, and the PLATFORM's pending intent decides which. n8n never branches on that.
    kind = 'contact';
    payload = {
      contact: {
        phone_number: String(inbound.contact.phoneNumber || ''),
        user_id: inbound.contact.userId,
        first_name: inbound.contact.firstName || undefined,
        last_name: inbound.contact.lastName || undefined
      },
      username: inbound.handle ? String(inbound.handle).replace(/^@/, '') : undefined
    };
  } else if (inbound.kind === 'text' && text.charAt(0) === '/') {
    // That is the whole test. Which command it is, whether it exists, what its arguments
    // mean and what to say about a typo are all the backend's now.
    kind = 'slash';
  }
}

return [{ json: Object.assign({}, sync, { _kind: kind, _payload: payload }) }];

// The backend words every ordinary outcome AND attaches a channel-ready `reply` to it, so
// the common paths — the credential, every refusal, the request_contact keyboard — arrive
// here already renderable and pass straight through.
//
// This covers the rest: a genuine error envelope carries a sentence but no envelope.
//
// ⚠ It wraps the BACKEND'S sentence and never writes one. That is what keeps "the bot relays,
// never renders" true here — n8n holds no copy table and no button labels, only the two wire
// shapes, and those come from channel-reply.ts on every other path.
const r = $input.first().json || {};
if (r.reply) { return [{ json: r }]; }

const inbound = $('Inbound').first().json;
const text = (r.error && (r.error.customerMessage || r.error.message)) || '';

// No sentence at all means there is nothing honest to say; `has reply?` sends this to the
// model rather than leaving the customer in silence. On this surface an empty 200 is still
// a TURN — the lesson the address-picker taught on 2026-09-06.
if (!text) { return [{ json: Object.assign({}, r, { reply: null }) }]; }

const reply = inbound.channel === 'telegram'
  ? { channel: 'telegram', method: 'sendMessage', body: { chat_id: inbound.externalId, text: text } }
  : { channel: 'whatsapp', method: 'messages', body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: inbound.externalId, type: 'text', text: { body: text, preview_url: false } } };

return [{ json: Object.assign({}, r, { reply: reply }) }];

// Is this customer mid-haggle, and did they just agree a price?
//
// TWO independent things, read from two keys, and they are not the same question. The
// FLAG says a negotiation is open, so this turn belongs to the seller. The LOCK says one
// just closed, so this turn belongs to the assistant — with a price to honour.
//
// Neither carries the vendor's floor or the asking price. The lock carries a reference,
// the variant it is bound to and what was agreed; nothing about the vendor's margin.
//
// ⚠ The n8n Redis node's `set` exposes NO TTL. That is measured, not assumed: it is the
// same limitation that put wi-mall-product-search's query cache in Postgres. So the
// `expiresAt` inside each value is the authority — a lapsed one is treated as absent
// here. Trusting a key's existence alone would hold a customer in bargaining mode for
// good if a close were ever missed, and would offer a long-dead price forever.
const inbound = $('Inbound').item.json;
const sync = $('sync identity').item.json;

const rawFlag = $('check bargain').item.json.bargainFlag;
const rawLock = $input.item.json.priceLock;

function parse(raw) {
  try { return raw ? JSON.parse(String(raw)) : null; } catch (e) { return null; }
}
function unexpired(v) {
  return !!v && !!v.expiresAt && new Date(v.expiresAt).getTime() > Date.now();
}

const flag = parse(rawFlag);
const live = !!flag && !!flag.variantId && unexpired(flag);

// A photo, a location pin or a shared contact mid-haggle is not a haggle. The bargaining
// agent has seven tools and none of them touches a file, an address or an order, so those
// turns stay with the main agent — and the flag stays set, so the next typed message goes
// back to the negotiation where it left off.
const bargaining = live && inbound.kind === 'text';

// The agreed price, rendered for the system prompt. Deliberately DATA and no instruction:
// what to do with it is written once, statically, in the prompt itself, so this line does
// not become a second place the rule lives.
//
// ⚠ THREE states, not two, and the third is why this is no longer a ternary. A lapsed
// lock used to render identically to no lock at all — both 'none' — so the assistant
// could not tell "we agreed 16,000 and it ran out" from "no negotiation ever happened".
// Measured 2026-09-08: a customer came back 76 minutes after a deal, was told the bot had
// no record of it and never confirms prices that way, and was asked whether the figure
// came from a screenshot somewhere else. It had agreed the price itself, 20 minutes
// before the lock lapsed. Both records had gone: this one by design, the chat transcript
// because its Redis TTL was an hour.
//
// The lapsed branch carries the price and the variant so the assistant can name what
// expired, and deliberately NOT the ref. A lapsed ref is refused at consume (plan D-10),
// so handing it over buys a guaranteed 4xx and hands a model a credential it cannot spend.
const EXPIRED_GRACE_MS = 24 * 60 * 60 * 1000;

const lock = parse(rawLock);
const lockExpiryMs = (lock && lock.expiresAt) ? new Date(lock.expiresAt).getTime() : 0;
const sinceExpiryMs = lockExpiryMs ? (Date.now() - lockExpiryMs) : -1;

// ⚠ The grace horizon is not cosmetic. The lock key has no Redis TTL of its own — see the
// note above — so it survives until something overwrites it. Without a bound, a customer
// who haggled once in March is told about that deal every turn, forever.
const lapsed = !!lock
  && lockExpiryMs > 0
  && sinceExpiryMs > 0
  && sinceExpiryMs < EXPIRED_GRACE_MS;

let agreedPrice = 'none';
if (lock && lock.ref && unexpired(lock)) {
  agreedPrice = 'ref ' + String(lock.ref)
    + ' · variantId ' + String(lock.variantId || 'unknown')
    + ' · quantity ' + String(lock.quantity || 1);
} else if (lapsed) {
  agreedPrice = 'expired'
    + ' · unitPrice ' + String(lock.unitPrice || 'unknown')
    + ' · variantId ' + String(lock.variantId || 'unknown')
    + ' · quantity ' + String(lock.quantity || 1)
    + ' · expiredMinutesAgo ' + String(Math.max(1, Math.round(sinceExpiryMs / 60000)));
}

return { json: {
  bargaining: bargaining,
  agreedPrice: agreedPrice,
  mode: 'turn',
  channel: inbound.channel,
  externalId: inbound.externalId,
  messageId: inbound.messageId,
  text: inbound.text,
  language: (sync && sync.data && sync.data.customer && sync.data.customer.language) || inbound.language || 'fr',
  variantId: live ? flag.variantId : null,
  productId: live ? (flag.productId || null) : null,
  quantity: live ? (Number(flag.quantity) > 0 ? Math.trunc(Number(flag.quantity)) : 1) : 1,
} };
